ceholder="Bericht" maxlength="5000" required><?php echo htmlspecialchars($formMessage); ?></textarea></div><div class="tm-text-right"><button type="submit" class="btn tm-btn tm-btn-big">Verzenden</button></div></form><div class="zz-form-note">Deze site wordt beschermd door reCAPTCHA. Het <a href="privacy.php">privacybeleid</a> en de <a href="terms.php">algemene voorwaarden</a> van Google zijn van toepassing.</div></div></div><div class="col-xl-7 col-lg-6 col-md-12 tm-contact-right"><div class="zz-contact-copy"><h2>Klachtenportaal</h2><div class="zz-dynamic-content text-content"><?php $filePath='complain.txt';if(file_exists($filePath)){echo nl2br(htmlspecialchars(file_get_contents($filePath)));}else{echo '-';} ?></div></div></div></section><footer class="container tm-footer"><div class="row tm-footer-row zz-footer-row"><p class="col-md-6 col-sm-12 mb-0">Auteursrecht &copy; <?php echo date('Y'); ?> ZZpzo</p><div class="col-md-6 col-sm-12 zz-footer-links"><a href="terms.php">Algemene voorwaarden</a><a href="complain.php">Klachtenportaal</a><a href="privacy.php">Privacybeleid</a></div></div></footer><script src="js/jquery-1.9.1.min.js?id=<?php echo filemtime('js/jquery-1.9.1.min.js'); ?>"></script><script src="js/bootstrap.min.js?id=<?php echo filemtime('js/bootstrap.min.js'); ?>"></script><script src="js/zz-form-height.js?id=<?php echo filemtime('js/zz-form-height.js'); ?>"></script><script>(function(){window.addEventListener('load',function(){var f=document.getElementById('form-feedback');if(f){setTimeout(function(){f.scrollIntoView({behavior:'smooth',block:'center'});},220);}});})();</script></body></html>